UPDATE conversation_memory_snapshot
SET status = 'superseded'
WHERE user_id = #{userId}
  AND session_id = #{sessionId}
  AND memory_version = #{memoryVersion}
  AND status = 'active'
  AND deleted = 0


        AND (tenant_id IS NULL OR tenant_id = '')


        AND tenant_id = #{tenantId}

UPDATE conversation_memory_snapshot SET status = 'stale'
WHERE user_id = #{userId} AND session_id = #{sessionId}
  AND covered_to_sequence >= #{minInvalidSequence}
  AND status IN ('active', 'superseded') AND deleted = 0
AND (tenant_id IS NULL OR tenant_id = '')AND tenant_id = #{tenantId}

